-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
-- New tables are readable by nusantara_readonly through the default privileges
-- of 20260815060658. The application role gets read and write, never DELETE.

GRANT SELECT, INSERT, UPDATE ON
  "Rack", "Reason", "Salesperson",
  "GradingCriterion", "GradingOption", "GradingRule", "GradingRuleOption",
  "SkuAxisValue", "AppleDbHiddenModel",
  "StockIn", "StockAdjustment",
  "CustomerAddress", "OrderFee", "UnitReturn",
  "Expense", "ManualIncome", "PaymentLog",
  "Settlement", "SettlementFee", "SettlementLog",
  "ServiceVisit", "ServiceFee",
  "SupplierDeposit", "DepositAllocation",
  "OpnameScopeLocation", "OpnameScopeRack", "OpnameScopeCategory",
  "OpnameScopeCondition", "OpnameSurplus"
TO nusantara_app;

-- Logs are append-only, the rule UnitEvent and AuditLog already follow
-- (invariant 14): what a payment was BEFORE somebody edited it is the whole
-- reason the log exists.
REVOKE UPDATE ON "PaymentLog", "SettlementLog", "StockIn", "StockAdjustment"
  FROM nusantara_app;

-- The change feed browsers poll. A technical log, not business history: the
-- application prunes rows past the retention window, which makes this the one
-- table in this migration it may DELETE from.
GRANT SELECT, INSERT, DELETE ON "StoreChange" TO nusantara_app;
GRANT USAGE, SELECT ON SEQUENCE "StoreChange_id_seq" TO nusantara_app;

-- The agent books holds through packages/db/src/reservations.ts, which records
-- what it changed so the tills see the hold.
GRANT SELECT, INSERT ON "StoreChange" TO nusantara_agent;
GRANT USAGE, SELECT ON SEQUENCE "StoreChange_id_seq" TO nusantara_agent;

-- Refuse to finish if the ledger's append-only rule has become a convention.
DO $check$
BEGIN
  IF has_table_privilege('nusantara_app', '"UnitEvent"', 'UPDATE')
     OR has_table_privilege('nusantara_app', '"UnitEvent"', 'DELETE')
     OR has_table_privilege('nusantara_app', '"PaymentLog"', 'UPDATE')
     OR has_table_privilege('nusantara_app', '"Unit"', 'DELETE') THEN
    RAISE EXCEPTION 'store_on_postgres: an append-only or never-deleted table is writable by nusantara_app';
  END IF;
END
$check$;
